"use client"

import * as React from "react"
import * as TogglePrimitive from "@radix-ui/react-toggle"

import { useComposedRefs } from "@/lib/0nlytype/refs"
import { cn } from "@/lib/utils"

type ToggleProps = Omit<React.ComponentProps<typeof TogglePrimitive.Root>, "asChild"> & {
  /**
   * The sign a held word wears. fermata: an arc is sketched over the word, a dot lands under it, and the word
   * leans into the italic. tenuto: a pen runs along a line under the word and rewrites it in the italic as it passes.
   * aside: a small note in our voice is hung beside the held word on a hairline arrow. guides: the two lines the word
   * is set on, baseline and x-height, are drawn through it in dots.
   */
  variant?: "fermata" | "tenuto" | "aside" | "guides"
  /** aside only: what the note beside the held word says. */
  note?: string
  /** Pins a state for documentation ("hover", "focus"); set on the root. */
  "data-force"?: string
}

/**
 * The word and its italic copy start at the same edge but aren't the same width, so a mark centred on
 * the button would sit off the word you see. This reads both widths (--ot-toggle-r, --ot-toggle-i) and
 * the stylesheet centres or ends the marks on whichever face is showing. Fonts arriving and resizes put
 * the marks straight there (data-still); only a press moves them.
 */
function useFaces(variant: string, children: React.ReactNode) {
  const ref = React.useRef<HTMLButtonElement | null>(null)
  React.useLayoutEffect(() => {
    const button = ref.current
    const label = button?.firstElementChild as HTMLElement | null
    const roman = label?.firstElementChild as HTMLElement | null
    if (!button || !label?.dataset.text || !roman || variant === "tenuto") return
    // The face's own width: its box less the overhang (--over) it keeps on each side, whatever the box-sizing.
    const width = (cs: CSSStyleDeclaration) =>
      `${parseFloat(cs.width) - (cs.boxSizing === "border-box" ? parseFloat(cs.paddingLeft) + parseFloat(cs.paddingRight) : 0)}px`
    const read = () => {
      button.setAttribute("data-still", "")
      button.style.setProperty("--ot-toggle-r", width(getComputedStyle(roman)))
      button.style.setProperty("--ot-toggle-i", width(getComputedStyle(label, "::after")))
      void button.offsetWidth
      button.removeAttribute("data-still")
    }
    read()
    const resize = new ResizeObserver(read)
    resize.observe(label)
    resize.observe(roman)
    return () => resize.disconnect()
  }, [variant, children])
  return ref
}

/**
 * A word you can hold down: a native button with aria-pressed. Held, the word is yours, so it turns italic.
 * The label shares its grid cell with an italic copy of itself (drawn by the stylesheet from data-text),
 * so the button is always as wide as its wider state and nothing beside it moves.
 */
function Toggle({ className, variant = "fermata", note = "on", children, ref, ...props }: ToggleProps) {
  const ownRef = useFaces(variant, children)
  const composedRef = useComposedRefs(ownRef, ref)
  return (
    <TogglePrimitive.Root
      ref={composedRef}
      data-slot="toggle"
      data-variant={variant}
      className={cn("ot-toggle", className)}
      {...props}
    >
      <span className="ot-toggle-label" data-text={typeof children === "string" ? children : undefined}>
        <span>{children}</span>
        {variant === "aside" ? (
          <small className="ot-toggle-note" aria-hidden="true">
            <span className="ot-toggle-arrow" />
            {note}
          </small>
        ) : null}
      </span>
    </TogglePrimitive.Root>
  )
}

export { Toggle, type ToggleProps }

@layer components {
  /* How much of the mark is drawn, 0 to 1: the fermata's arc, or the tenuto's pencil line. */
  @property --ot-toggle-draw { syntax: "<number>"; inherits: true; initial-value: 0; }
  /* How far the pen has rewritten the word, 0 to 1: the tenuto's ink line and its italic. */
  @property --ot-toggle-ink { syntax: "<number>"; inherits: true; initial-value: 0; }

  /* ── ot-toggle ── a word you can hold down. Held, it's yours, so it turns italic: under the fermata, or over the tenuto.
     Marks pass through. --e anchors a mark at its start (0) while it draws and at its end (1) while it leaves, so a stroke
     always travels the way you read; it flips only when the mark is whole or gone, so the flip never shows. --ie does the
     same for the tenuto's ink. Both variants share one box, room for the arc above and the line below, so a fermata
     and a tenuto side by side stand on one baseline. */
  .ot-toggle {
    --dir: 1; --e: 1; --ie: 1; --y: 0.3em;
    --w: var(--ot-toggle-r, 100%); /* the width of the face you see: the roman, or held, the italic (measured by toggle.tsx) */
    position: relative; appearance: none; border: 0; background: none; margin: 0; padding: 0.8em 0 var(--y);
    font: inherit; color: var(--ot-graphite); cursor: pointer; -webkit-tap-highlight-color: transparent;
    transition: color var(--ot-allegro), font-weight var(--ot-andante) var(--ot-exhale), font-stretch var(--ot-andante) var(--ot-exhale), --ot-toggle-draw var(--ot-moderato) var(--ot-exhale), --ot-toggle-ink var(--ot-andante) var(--ot-breath);
  }
  .ot-toggle:is([dir="rtl"], [dir="rtl"] *) { --dir: -1; }
  .ot-toggle:is(:hover, [data-force~="hover"]):not(:disabled) { color: var(--ot-ink); }
  .ot-toggle:is(:hover, [data-force~="hover"]):not(:disabled), .ot-toggle[data-state="on"] { --ot-toggle-draw: 1; --e: 0; }
  .ot-toggle[data-state="on"] { --ot-toggle-ink: 1; --ie: 0; --w: var(--ot-toggle-i, 100%); color: var(--ot-ink); }
  .ot-toggle:disabled { color: var(--ot-pencil); opacity: 0.55; cursor: not-allowed; }

  /* The word and its italic copy share one cell, so the button is as wide as its wider state. Each overhangs the cell by
     --over on every side, so a mask over it never trims the italic's swashes, and the pen's line can run past the ends. */
  .ot-toggle-label { --over: 0.15em; display: inline-grid; align-items: baseline; white-space: nowrap; text-align: start; } /* the word stands where its label does */
  .ot-toggle-label > span, .ot-toggle-label::after {
    grid-area: 1 / 1; padding: var(--over); margin: calc(var(--over) * -1); transform-origin: 0 calc(100% - var(--over) - 0.25em);
    transition: opacity var(--ot-moderato) var(--ot-breath), transform var(--ot-moderato) var(--ot-exhale), color var(--ot-allegro);
  }
  .ot-toggle-label::after {
    content: attr(data-text) / "";
    --over: calc(0.15em / var(--ot-expression-scale)); /* the same length as the word's, in the italic's larger em */
    font-family: var(--ot-expression); font-style: italic; font-weight: 400; font-size: calc(var(--ot-expression-scale) * 1em); line-height: 1;
    color: var(--ot-ink); opacity: 0; transform: skewX(12deg);
  }
  /* Apart from the tenuto, whose pen wipes the whole cell, each face keeps its own width, so the marks can find it. */
  .ot-toggle:not([data-variant="tenuto"]) > .ot-toggle-label > span, .ot-toggle:not([data-variant="tenuto"]) > .ot-toggle-label::after { justify-self: start; }
  /* A label that holds elements has no copy; it turns italic in place. */
  .ot-toggle[data-state="on"] > .ot-toggle-label:not([data-text]) > span { font-family: var(--ot-expression); font-style: italic; font-size: calc(var(--ot-expression-scale) * 1em); }

  .ot-toggle::before, .ot-toggle::after { content: ""; position: absolute; pointer-events: none; }
  /* Measuring (fonts arriving, a resize) isn't a choice: the marks go straight there. */
  .ot-toggle[data-still], .ot-toggle[data-still]::before, .ot-toggle[data-still]::after,
  .ot-toggle[data-still] *, .ot-toggle[data-still] *::before, .ot-toggle[data-still] *::after { transition: none; }

  /* ── fermata (the default): the sign for a note held longer than written.
     Pointing sketches the arc in pencil from its start foot; held, it inks, the dot lands under it, and the word
     leans into the italic: the roman shears forward as it fades, and the italic arrives upright and settles into its slant. */
  /* The sign stands over the middle of the face you see, so it slides over as the word leans into its wider or narrower italic. */
  .ot-toggle:is([data-variant="fermata"], :not([data-variant]))::before, .ot-toggle:is([data-variant="fermata"], :not([data-variant]))::after { inset-inline-start: calc(var(--w) / 2); }
  .ot-toggle:is([data-variant="fermata"], :not([data-variant]))::before {
    top: 0; width: 1em; height: 0.5em; margin-inline-start: -0.5em; box-sizing: border-box;
    border: var(--ot-hairline) solid var(--ot-rule-strong); border-bottom: 0; border-radius: 0.5em 0.5em 0 0;
    scale: var(--dir) 1; /* drawn from the start foot, which is the right one right to left */
    mask: conic-gradient(from -90deg at 50% 100%, #0000 calc(var(--e) * (1 - var(--ot-toggle-draw)) * 180deg), #000 0 calc((var(--e) * (1 - var(--ot-toggle-draw)) + var(--ot-toggle-draw)) * 180deg), #0000 0);
    transition: border-color var(--ot-allegro), border-width var(--ot-allegro), translate var(--ot-moderato) var(--ot-spiccato), inset-inline-start var(--ot-moderato) var(--ot-exhale);
  }
  .ot-toggle:is([data-variant="fermata"], :not([data-variant]))::after {
    --dot: max(0.24em, 4px);
    top: calc(0.5em - var(--dot) * 1.15); width: var(--dot); height: var(--dot); margin-inline-start: calc(var(--dot) / -2); border-radius: 50%;
    background: var(--ot-ink); scale: 0; translate: 0 -0.3em;
    transition: scale var(--ot-allegro) var(--ot-breath), translate var(--ot-allegro) var(--ot-breath), inset-inline-start var(--ot-moderato) var(--ot-exhale);
  }
  .ot-toggle:is([data-variant="fermata"], :not([data-variant]))[data-state="on"]::before { border-color: var(--ot-ink); border-width: var(--ot-stroke); }
  .ot-toggle:is([data-variant="fermata"], :not([data-variant]))[data-state="on"]::after { /* the arc arrives, then the dot lands */
    scale: 1; translate: none;
    transition: scale var(--ot-moderato) var(--ot-spiccato) calc(var(--ot-moderato) * 0.45), translate var(--ot-moderato) var(--ot-spiccato) calc(var(--ot-moderato) * 0.45), inset-inline-start var(--ot-moderato) var(--ot-exhale);
  }
  .ot-toggle:is([data-variant="fermata"], :not([data-variant])):active:not(:disabled)::before { translate: 0 0.12em; transition-duration: var(--ot-allegro); } /* pressed, the sign comes down toward the word */
  /* The lean, for every variant but the tenuto: the face going out fades fast and the one coming in takes its time,
     so the two are seldom seen at once. */
  .ot-toggle:not([data-variant="tenuto"]) > .ot-toggle-label::after,
  .ot-toggle:not([data-variant="tenuto"])[data-state="on"] > .ot-toggle-label[data-text] > span { transition-duration: var(--ot-allegro), var(--ot-moderato), var(--ot-allegro); }
  .ot-toggle:not([data-variant="tenuto"])[data-state="on"] > .ot-toggle-label[data-text] > span { opacity: 0; transform: skewX(-12deg); }
  .ot-toggle:not([data-variant="tenuto"])[data-state="on"] > .ot-toggle-label::after { opacity: 1; transform: none; transition-duration: var(--ot-moderato); }

  /* ── tenuto: the line under a note held its full value. Pointing sketches it in pencil. Held, a pen inks it from the
     start, and behind the pen the word is rewritten in the italic. Released, the pen passes again, the ink leaves ahead
     of it and the roman comes back behind it. The line, the pen and both masks read one number, so they never part. */
  .ot-toggle[data-variant="tenuto"]::before {
    inset-inline: -0.15em; bottom: calc(var(--y) - var(--ot-stroke) / 2); height: var(--ot-stroke);
    background:
      linear-gradient(var(--ot-ink) 0 0) no-repeat calc((0.5 + (var(--ie) - 0.5) * var(--dir)) * 100%) 0 / calc(var(--ot-toggle-ink) * 100%) 100%,
      linear-gradient(var(--ot-rule-strong) 0 0) no-repeat calc((0.5 + (var(--e) - 0.5) * var(--dir)) * 100%) 100% / calc(var(--ot-toggle-draw) * 100%) var(--ot-hairline);
  }
  .ot-toggle[data-variant="tenuto"]::after { /* the pen: where the ink has reached, coming or going, seen only while it moves */
    --dot: max(0.2em, 4px);
    inset-inline-start: calc(-0.15em + (100% + 0.3em) * (var(--ie) + var(--ot-toggle-ink) * (1 - 2 * var(--ie)))); bottom: calc(var(--y) - var(--dot) / 2);
    width: var(--dot); height: var(--dot); margin-inline-start: calc(var(--dot) / -2); border-radius: 50%;
    background: var(--ot-ink); opacity: clamp(0, 12 * var(--ot-toggle-ink) * (1 - var(--ot-toggle-ink)), 1);
  }
  .ot-toggle[data-variant="tenuto"] > .ot-toggle-label[data-text] > span { mask: linear-gradient(#000 0 0) no-repeat calc((0.5 - (var(--ie) - 0.5) * var(--dir)) * 100%) 0 / calc((1 - var(--ot-toggle-ink)) * 100%) 100%; }
  .ot-toggle[data-variant="tenuto"] > .ot-toggle-label::after { opacity: 1; transform: none; mask: linear-gradient(#000 0 0) no-repeat calc((0.5 + (var(--ie) - 0.5) * var(--dir)) * 100%) 0 / calc(var(--ot-toggle-ink) * 100%) 100%; }

  /* ── aside: after "It has to be design.", where a small note in the roman is tucked into the italic's shoulder on a
     hairline arrow. Held, the word is yours and leans into the italic; beside it, in our voice, the note says what that
     means. It stands on the word's baseline, under an arrow that points back at the word. Pointing
     sketches the arrow in pencil, reaching toward the word; held, it inks, its head lands and the note writes in.
     The note hangs into the space after the word, like a margin note: it takes no room, so leave it some. */
  .ot-toggle-note {
    --gap: 0.45em; --len: 2.6em;
    grid-area: 1 / 1; align-self: baseline; justify-self: start; width: 0; white-space: nowrap; pointer-events: none;
    margin-inline: calc(var(--w) + var(--gap)) calc(-1 * (var(--w) + var(--gap)));
    font-family: var(--ot-voice); font-style: normal; font-weight: 400; font-size: var(--ot-pp); line-height: 1; letter-spacing: var(--ot-pp-tr);
    color: transparent;
    transition: margin-inline var(--ot-moderato) var(--ot-exhale), color var(--ot-allegro);
  }
  .ot-toggle[data-state="on"] .ot-toggle-note { color: var(--ot-graphite); transition: margin-inline var(--ot-moderato) var(--ot-exhale), color var(--ot-moderato) var(--ot-exhale) var(--ot-allegro); }
  /* The arrow's box stands on the baseline and reaches a little over the note's capitals; the text starts under its tip. */
  .ot-toggle-arrow {
    display: inline-block; vertical-align: baseline; position: relative; width: var(--len); height: 1.15em; height: calc(1cap + 0.5em); margin-inline-end: calc(var(--len) * -1);
    color: var(--ot-rule-strong); transition: color var(--ot-allegro);
  }
  .ot-toggle[data-state="on"] .ot-toggle-arrow { color: var(--ot-ink); }
  .ot-toggle-arrow::before, .ot-toggle-arrow::after { content: ""; position: absolute; top: 0; box-sizing: border-box; }
  .ot-toggle-arrow::before { /* the shaft, drawn from its far end toward the word */
    inset-inline: 0; border-top: var(--ot-hairline) solid currentColor;
    transform-origin: calc((0.5 + 0.5 * var(--dir)) * 100%) 0; scale: var(--ot-toggle-draw) 1;
  }
  .ot-toggle-arrow::after { /* the head: a corner turned to point back, landing as the ink arrives */
    inset-inline-start: 0; width: 0.36em; height: 0.36em; border-top: var(--ot-hairline) solid currentColor; border-inline-start: var(--ot-hairline) solid currentColor;
    transform-origin: calc((0.5 - 0.5 * var(--dir)) * 100%) 0; rotate: calc(-45deg * var(--dir));
    opacity: clamp(0, 3 * var(--ot-toggle-ink) - 2, 1);
  }

  /* ── guides: after Paul Rand's "design", set on its dotted construction grid. Held, the word is set: the two lines
     it stands between, the baseline and the x-height, are drawn through it in dots and run on past its ends. The
     italic is scaled until the two x-heights meet, so as the word leans into the italic its letters stay between the
     same two lines, and the lines show it. Pointing sketches the baseline alone; held, the x-height line draws over
     it. They pass through: each draws from the start and leaves toward the end. */
  .ot-toggle[data-variant="guides"] > .ot-toggle-label::before {
    --c: var(--ot-rule-strong); --run: 0.45em;
    content: ""; grid-area: 1 / 1; align-self: baseline; justify-self: start; pointer-events: none;
    width: calc(var(--w) + var(--run) * 2); margin-inline: calc(var(--run) * -1); height: calc(1ex + 1px);
    background: linear-gradient(to right, var(--c) 1px, #0000 0) repeat-x 0 0 / 3px 1px, linear-gradient(to right, var(--c) 1px, #0000 0) repeat-x 0 100% / 3px 1px;
    mask:
      linear-gradient(#000 0 0) no-repeat calc((0.5 + (var(--ie) - 0.5) * var(--dir)) * 100%) 0 / calc(var(--ot-toggle-ink) * 100%) 1px,
      linear-gradient(#000 0 0) no-repeat calc((0.5 + (var(--e) - 0.5) * var(--dir)) * 100%) 100% / calc(var(--ot-toggle-draw) * 100%) 1px;
    transition: width var(--ot-moderato) var(--ot-exhale);
  }

  /* Forced colours drop the colours of the marks: say what each one is. */
  @media (forced-colors: active) {
    .ot-toggle { color: ButtonText; }
    .ot-toggle:disabled { color: GrayText; }
    .ot-toggle:focus-visible, .ot-toggle[data-force~="focus"] { outline-color: Highlight; }
    .ot-toggle::before, .ot-toggle::after { forced-color-adjust: none; }
    .ot-toggle:is([data-variant="fermata"], :not([data-variant]))::before { border-color: GrayText; }
    .ot-toggle:is([data-variant="fermata"], :not([data-variant]))[data-state="on"]::before { border-color: ButtonText; }
    .ot-toggle:is([data-variant="fermata"], :not([data-variant]))::after, .ot-toggle[data-variant="tenuto"]::after { background: ButtonText; }
    .ot-toggle[data-variant="tenuto"]::before { background-image: linear-gradient(ButtonText 0 0), linear-gradient(GrayText 0 0); }
    .ot-toggle-note, .ot-toggle[data-variant="guides"] > .ot-toggle-label::before { forced-color-adjust: none; }
    .ot-toggle[data-state="on"] .ot-toggle-note { color: ButtonText; }
    .ot-toggle-arrow { color: GrayText; }
    .ot-toggle[data-state="on"] .ot-toggle-arrow { color: ButtonText; }
    .ot-toggle[data-variant="guides"] > .ot-toggle-label::before { --c: GrayText; }
  }
}
